package com.rustypayments.legacy;

import com.rustypayments.PaymentCalendar;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.temporal.ChronoUnit;
import java.util.Set;

public class LegacyPaymentCalendar implements PaymentCalendar {

    private static final ZoneId WARSAW = ZoneId.of("Europe/Warsaw");
    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ISO_LOCAL_DATE;
    private static final DateTimeFormatter INSTANT_FORMATTER = DateTimeFormatter.ISO_OFFSET_DATE_TIME;

    private static final Set<MonthDay> HOLIDAYS = Set.of(
        MonthDay.of(1, 1), MonthDay.of(1, 6), MonthDay.of(5, 1), 
        MonthDay.of(5, 3), MonthDay.of(8, 15), MonthDay.of(11, 1), 
        MonthDay.of(11, 11), MonthDay.of(12, 25), MonthDay.of(12, 26)
    );

    @Override
    public boolean isBusinessDay(String date) {
        LocalDate ld = parseDate(date);
        return isBusinessDay(ld);
    }

    @Override
    public String processingDate(String submittedAt) {
        ZonedDateTime zdt = parseInstant(submittedAt);
        LocalDate date = zdt.toLocalDate();
        LocalTime time = zdt.toLocalTime();

        if (isBusinessDay(date) && !time.isAfter(LocalTime.of(16, 0))) {
            return date.format(DATE_FORMATTER);
        }
        return nextBusinessDay(date).format(DATE_FORMATTER);
    }

    @Override
    public String settlementDate(String submittedAt) {
        LocalDate procDate = LocalDate.parse(processingDate(submittedAt), DATE_FORMATTER);
        return nextBusinessDay(procDate).format(DATE_FORMATTER);
    }

    @Override
    public int daysLate(String dueDate, String paidAt) {
        LocalDate due = parseDate(dueDate);
        ZonedDateTime paid = parseInstant(paidAt);
        LocalDate paidDate = paid.withZoneSameInstant(WARSAW).toLocalDate();
        long days = ChronoUnit.DAYS.between(due, paidDate);
        return (int) Math.max(0, days);
    }

    @Override
    public String addMonths(String date, int months) {
        LocalDate ld = parseDate(date);
        boolean isEndOfMonth = ld.equals(ld.with(java.time.temporal.TemporalAdjusters.lastDayOfMonth()));
        LocalDate result = ld.plusMonths(months);
        if (isEndOfMonth) {
            result = result.with(java.time.temporal.TemporalAdjusters.lastDayOfMonth());
        }
        return result.format(DATE_FORMATTER);
    }

    private boolean isBusinessDay(LocalDate date) {
        DayOfWeek dow = date.getDayOfWeek();
        if (dow == DayOfWeek.SATURDAY || dow == DayOfWeek.SUNDAY) return false;
        return !HOLIDAYS.contains(MonthDay.from(date));
    }

    private LocalDate nextBusinessDay(LocalDate date) {
        LocalDate next = date.plusDays(1);
        while (!isBusinessDay(next)) next = next.plusDays(1);
        return next;
    }

    private LocalDate parseDate(String text) {
        try {
            LocalDate ld = LocalDate.parse(text, DATE_FORMATTER);
            if (!text.equals(ld.format(DATE_FORMATTER))) throw new DateTimeParseException("", text, 0);
            return ld;
        } catch (Exception e) {
            throw new IllegalArgumentException("Invalid date");
        }
    }

    private ZonedDateTime parseInstant(String text) {
        try {
            ZonedDateTime zdt = ZonedDateTime.parse(text, INSTANT_FORMATTER);
            if (text.contains("Z")) zdt = zdt.withZoneSameInstant(ZoneOffset.UTC);
            return zdt.withZoneSameInstant(WARSAW);
        } catch (Exception e) {
            throw new IllegalArgumentException("Invalid instant");
        }
    }
}

